<template><view class="page"><AppTopbar title="寻友" action="筛选"/><view class="notice">根据你的水平和可约时段，发现附近球友</view><BannerCarousel :banners="banners"/><view class="profile"><UserAvatar :name="profile.nickname"/><view class="copy"><text class="name">{{profile.nickname}}</text><text class="meta">{{profile.level}} · {{profile.region}}</text></view><text class="edit" @tap="uni.switchTab({url:'/pages/profile/profile'})">我的资料</text></view><text class="section">附近球友</text><FriendCard v-for="item in friends" :key="item.id" :friend="item" @open="openFriend"/></view></template>
<script setup>
import {ref} from 'vue';import {onShow} from '@dcloudio/uni-app';import AppTopbar from '../../components/AppTopbar.vue';import BannerCarousel from '../../components/BannerCarousel.vue';import UserAvatar from '../../components/UserAvatar.vue';import FriendCard from '../../components/FriendCard.vue';import {loadProfile} from '../../utils/storage';import {requireLogin} from '../../utils/auth';import {callCloud} from '../../utils/cloud'
const profile=ref(loadProfile({nickname:'羽球新人',region:'武汉',availability:'周末晚上',level:'待测评',tags:['等待首次测评']}));const banners=ref([{id:'local-1',title:'同校约球，轻松找到搭子',description:'按水平、地区和时间发现合适球友'},{id:'local-2',title:'完成自测，记录动作进步',description:'用同机位视频对比每次训练趋势'}]);const friends=ref([{id:1,nickname:'小林同学',region:'洪山区',availability:'周六晚',level:'入门至初级',tags:['高远球稳定','步法待提升']},{id:2,nickname:'阿杰',region:'武昌区',availability:'周日上午',level:'初级',tags:['双打默契','网前积极']},{id:3,nickname:'Momo',region:'光谷',availability:'工作日 19:00 后',level:'入门水平',tags:['想练高远球','可新手友好']}]);
onShow(()=>{if(!requireLogin())return;profile.value=loadProfile(profile.value);callCloud('listBanners',{}).then(r=>{if(r.banners?.length)banners.value=r.banners}).catch(()=>{})});function openFriend(friend){uni.showModal({title:friend.nickname,content:`${friend.region} · ${friend.availability}
${friend.tags.join('、')}`,confirmText:'发起聊天',success:r=>{if(r.confirm)uni.switchTab({url:'/pages/chat/chat'})}})}
</script>
<style scoped>.page{min-height:100vh;padding-bottom:40rpx}.notice{padding:24rpx 32rpx;color:#777;font-size:25rpx}.profile{margin:26rpx 24rpx 30rpx;padding:26rpx 24rpx;display:flex;align-items:center;background:#fff;border-radius:12rpx}.copy{flex:1;margin-left:20rpx}.name{display:block;font-size:31rpx;font-weight:600}.meta{display:block;margin-top:8rpx;color:#888;font-size:24rpx}.edit{color:#576b95;font-size:25rpx}.section{display:block;padding:0 32rpx 18rpx;color:#888;font-size:25rpx}</style>
